.confirm__msg {
  margin: 0 0 16px;
  /* The scrollable region once the box hits its max-height, so the action buttons
     below stay on-screen instead of being pushed past the viewport. */
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  font-size: 13px;
  line-height: 1.5;
  color: var(--text);
  /* Confirm messages are composed as paragraphs separated by `\n\n` — the safety disclosures most
     of all ("⚠ The worktree directory will be DELETED", "⚠ N uncommitted file(s)", "⚠ … is also
     pushed to origin", the device-approval SAS code). Without this they collapse into one run-on
     paragraph and the warning the user most needs to see is buried mid-sentence. `pre-line` keeps
     the newlines and still collapses runs of spaces, exactly as `normal` did — so the messages that
     carry no newlines at all are unchanged. */
  white-space: pre-line;
  /* `pre-line` only breaks at whitespace, so one long unbroken token — a URL, an absolute path,
     a base64 blob, all common in the agent-authored text the canvas-control write approval shows
     ("Agent X wants to send…") — forced the message area into HORIZONTAL scrolling. Measured in
     Chrome: a 400-char token overflows at any box width; with this it wraps and the overflow is
     gone. A dialog whose whole job is "read this, then approve it" must never hide half the text
     off to the side. */
  overflow-wrap: anywhere;
}
